#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
TASK_TEST_DIR=$(mktemp -d "${TMPDIR:-/tmp}/neo-orange-unit.XXXXXX")
trap 'rm -rf "$TASK_TEST_DIR"' EXIT
"${JAVA_HOME:?Set JAVA_HOME}/bin/javac" -d "$TASK_TEST_DIR" src/studio/jiayu/neoagent/{UpdateRules,WorkflowPlanException,WorkflowIntentRules,SharedAppSourceRules,StageSourceRules,CandidateRoutingRules,ActionEnvelopeRules,VoiceIntentRules,AgentImeRules,VisualActionRules,ScreenshotWait,VoiceSession,VoiceEndpointRules,VoiceCaptureRules,GameplayIntent,TaskMemory,PixelScene,SearchInputRules,SearchSubmitRules,WindowFrame,SearchTarget,MutationRules,MovieBoundaryStop,DocumentEditContract,DocumentReadback,DocumentScope,RunOwnership,MemoryRules,RejectedActions,HealthRules,TouchPointPicker,TaskBoundary,PrivateText,RecoveryPolicy,DocumentText,CaptureRules,DocumentInputRules,DocumentReopen,PlanCoverage,TaskScope,ShoppingIntent,PurchasePolicy,PurchaseFacts,PurchaseState,RouteIntent,SearchQueryPolicy,ActionGuard,CommerceReadbackRules,FooterLabelRules,CheckoutReviewEvidence,OrderEvidenceRules,VariantRules}.java tests/debug-src/studio/jiayu/neoagent/{VoiceQaMode,VoiceQaModeTest,VoicePcmRules,VoicePcmRulesTest}.java tests/touch/{UpdateRulesTest,PlannerFeedbackTest,SharedAppSourceRulesTest,StageSourceRulesTest,ActionEnvelopeRulesTest,VoiceIntentRulesTest,AgentImeRulesTest,VisualActionRulesTest,ScreenshotWaitTest,VoiceSessionTest,VoiceEndpointRulesTest,VoiceCaptureRulesTest,GameplayIntentTest,TaskMemoryTest,PixelSceneTest,SearchInputRulesTest,SearchSubmitRulesTest,WindowFrameTest,SearchTargetTest,MovieBoundaryStopTest,DocumentEditContractTest,DocumentReadbackTest,RunOwnershipTest,MemoryRulesTest,RejectedActionsTest,HealthRulesTest,TouchPointPickerTest,TaskBoundaryTest,PrivateTextTest,RecoveryPolicyTest,DocumentTextTest,CaptureRulesTest,DocumentInputRulesTest,DocumentReopenTest,PlanCoverageTest,TaskScopeTest,PurchasePolicyTest,PurchaseStateTest,RouteIntentTest,SearchQueryPolicyTest,ActionGuardTest,CheckoutReviewEvidenceTest}.java
for TASK_CASE in UpdateRulesTest PlannerFeedbackTest SharedAppSourceRulesTest StageSourceRulesTest ActionEnvelopeRulesTest VoiceIntentRulesTest AgentImeRulesTest VoiceQaModeTest VoicePcmRulesTest VisualActionRulesTest ScreenshotWaitTest VoiceSessionTest VoiceEndpointRulesTest VoiceCaptureRulesTest GameplayIntentTest TaskMemoryTest PixelSceneTest SearchInputRulesTest SearchSubmitRulesTest WindowFrameTest SearchTargetTest MovieBoundaryStopTest DocumentEditContractTest DocumentReadbackTest RunOwnershipTest MemoryRulesTest RejectedActionsTest HealthRulesTest TouchPointPickerTest TaskBoundaryTest PrivateTextTest RecoveryPolicyTest DocumentTextTest CaptureRulesTest DocumentInputRulesTest DocumentReopenTest PlanCoverageTest TaskScopeTest PurchasePolicyTest PurchaseStateTest RouteIntentTest SearchQueryPolicyTest ActionGuardTest CheckoutReviewEvidenceTest; do
 "${JAVA_HOME}/bin/java" -cp "$TASK_TEST_DIR" "studio.jiayu.neoagent.$TASK_CASE"
done
